        HeldOutSplit s = HeldOutSplit_Make(1000, 0.20);
        HeldOutSplit_Unlock(&s, s.lock_token);
        BacktestResults dummy;
        BacktestResults_Init(&dummy);
        FullValidationResults out = {};
