        ControllerConfig<FP> cfg = ControllerConfig_Default<FP>();
        cfg.starting_balance = FPN_FromDouble<FP>(10000.0);
        PortfolioController<FP> ctrl = {};
        PortfolioController_Init(&ctrl, cfg);

