    printf("\n--- v5.12.2.B: lazy slow-path rebuild ---\n");
    {
        // Phase 2.B of v5.12. Skips RebuildOneCore body when slow_state
        // hasn't changed materially (small price delta + within
        // force_period_us). Default cfg.lazy_rebuild_enabled=0 → always
        // rebuild; existing 1944 tests verify bytewise preservation.
        // Enabled-mode behavior is integration-tested via replay harness.

        // === Test 1: cfg defaults ===
        ControllerConfig<64> cfg = ControllerConfig_Default<64>();
        check("v5.12.2.B: default cfg.lazy_rebuild_enabled == 0",
              cfg.lazy_rebuild_enabled == 0);
        check("v5.12.2.B: default cfg.lazy_rebuild_force_period_us == 1_000_000",
              cfg.lazy_rebuild_force_period_us == 1000000ULL);
        check("v5.12.2.B: default cfg.lazy_rebuild_price_threshold_pct == 0.0005",
              std::fabs(FPN_ToDouble(cfg.lazy_rebuild_price_threshold_pct)
                        - 0.0005) < 1e-9);

        // === Test 2: FPN abs via sign-bit clear (used by lazy predicate) ===
        FPN<64> a = FPN_FromDouble<64>(100.5);
        FPN<64> b = FPN_FromDouble<64>(101.0);
        FPN<64> delta = FPN_Sub(a, b);  // negative
        check("v5.12.2.B: FPN_Sub(100.5, 101.0) sign == 1 (negative)",
              delta.sign == 1);
        FPN<64> abs_delta = delta;
        abs_delta.sign = 0;
        check("v5.12.2.B: |delta| via sign-bit clear → magnitude same",
              FPN_MagEq<64>(abs_delta, delta));
        check("v5.12.2.B: |delta| sign cleared",
              abs_delta.sign == 0);

        // === Test 3: relative delta math at threshold boundary ===
        // |100.5 - 101.0| / 101.0 ≈ 0.00495 > 0.0005 → would trigger rebuild
        FPN<64> rel = FPN_DivNoAssert(abs_delta, b);
        check("v5.12.2.B: rel_delta(100.5, 101.0) > 0.0005 threshold",
              FPN_GreaterThan(rel, cfg.lazy_rebuild_price_threshold_pct));

        // === Test 4: small price change → below threshold ===
        // 100.04 vs 100.0 → rel_delta = 0.0004 < 0.0005 threshold → SKIP
        FPN<64> p1 = FPN_FromDouble<64>(100.0);
        FPN<64> p2 = FPN_FromDouble<64>(100.04);
        FPN<64> small_delta = FPN_Sub(p2, p1);
        small_delta.sign = 0;  // abs
        FPN<64> small_rel = FPN_DivNoAssert(small_delta, p1);
        check("v5.12.2.B: small price delta (0.04%) below 0.05% threshold",
              !FPN_GreaterThan(small_rel, cfg.lazy_rebuild_price_threshold_pct));
    }

    printf("\n--- v5.12.1.D: confidence-conditional sizing infra (REPLACED v5.14.9.B; lambda kept as historical reference) ---\n");
    {
        // **DEPRECATED v5.14.9.B**: the v5.12.1.D math at
        // StrategyParameters.hpp:1291-1322 has been replaced by the soft risk
        // degradation ladder (FOREACH_DEGRADATION_CURVE + per-core gate cache).
        // The lambda below mirrors the OLD formula; it stays for historical
        // reference. The actual engine code now dispatches through
        // Confidence_DegradationScale (tested in v5.14.9.A) + reads
        // MASK_LADDER_ACTIVE from per-core gate_state cache.
        //
        // Original v5.12.1.D scope: cfg field + multiplier plumbing in
        // ML_BuildParameters. Default cfg=0 → factor=1.0 → no behavior
        // change. Activation gated on Phase 4.B paper-test calibration.
        // Tests verify the factor math directly (the plumbing site is
        // exercised through the existing ML strategy build tests).

        auto compute_factor = [](int mode, double conf_now, double threshold) -> double {
            if (mode == 0) return 1.0;
            double denom = 1.0 - threshold;
            if (denom <= 1e-9 || conf_now < threshold) return 0.0;
            double raw = (conf_now - threshold) / denom;
            if (raw < 0.0) raw = 0.0;
            if (raw > 1.0) raw = 1.0;
            return (mode == 2) ? (raw * raw) : raw;
        };

        // === Test 1: default cfg.risk_scale_by_confidence == 0 ===
        ControllerConfig<64> cfg = ControllerConfig_Default<64>();
        check("v5.12.1.D: default cfg.risk_scale_by_confidence == 0",
              cfg.risk_scale_by_confidence == 0);

        // === Test 2: mode=0 (disabled) → factor = 1.0 (no change) ===
        check("v5.12.1.D: mode=0 → factor = 1.0",
              compute_factor(0, 0.95, 0.5) == 1.0);
        check("v5.12.1.D: mode=0 → factor = 1.0 even with low conf",
              compute_factor(0, 0.51, 0.5) == 1.0);

        // === Test 3: mode=1 (linear) ===
        // P=0.95, threshold=0.50 → factor = (0.45 / 0.50) = 0.90
        double f1 = compute_factor(1, 0.95, 0.50);
        check("v5.12.1.D: mode=1 P=0.95/thr=0.50 → factor ≈ 0.90",
              std::fabs(f1 - 0.90) < 1e-9);
        // P=0.51, threshold=0.50 → factor ≈ 0.02
        double f2 = compute_factor(1, 0.51, 0.50);
        check("v5.12.1.D: mode=1 P=0.51/thr=0.50 → factor ≈ 0.02",
              std::fabs(f2 - 0.02) < 1e-9);

        // === Test 4: mode=2 (quadratic) — steeper rolloff ===
        // P=0.95, threshold=0.50 → factor = 0.90^2 = 0.81
        double f3 = compute_factor(2, 0.95, 0.50);
        check("v5.12.1.D: mode=2 P=0.95/thr=0.50 → factor ≈ 0.81",
              std::fabs(f3 - 0.81) < 1e-9);
        // P=0.51, threshold=0.50 → factor ≈ 0.02^2 = 0.0004
        double f4 = compute_factor(2, 0.51, 0.50);
        check("v5.12.1.D: mode=2 P=0.51/thr=0.50 → factor ≈ 0.0004",
              std::fabs(f4 - 0.0004) < 1e-9);

        // === Test 5: P below threshold → factor = 0 (block) ===
        check("v5.12.1.D: mode=1 P<threshold → factor = 0",
              compute_factor(1, 0.40, 0.50) == 0.0);
        check("v5.12.1.D: mode=2 P<threshold → factor = 0",
              compute_factor(2, 0.40, 0.50) == 0.0);

        // === Test 6: P=threshold (boundary) → factor = 0 (no scale) ===
        check("v5.12.1.D: mode=1 P==threshold → factor = 0",
              compute_factor(1, 0.50, 0.50) == 0.0);

        // === Test 7: P=1.0 (max conf) → factor = 1.0 ===
        check("v5.12.1.D: mode=1 P=1.0 → factor = 1.0",
              std::fabs(compute_factor(1, 1.0, 0.50) - 1.0) < 1e-9);
        check("v5.12.1.D: mode=2 P=1.0 → factor = 1.0 (1^2 = 1)",
              std::fabs(compute_factor(2, 1.0, 0.50) - 1.0) < 1e-9);
    }

    printf("\n--- v5.12.1.B.3: hot-path staleness gate (branchless mask) ---\n");
    {
        // Phase B.3 of v5.12.1.B. Hot-path mask check uses
        //   tick.sequence - cached_publish_tick > param_max_age_ticks
        // gated by GATE_FLAG_STALENESS_ENABLED and a non-zero stamp.
        //
        // We test the mask compute directly (mirroring the inlined logic
        // in ExecutionCore_Tick) since synthesizing a full ExecutionCore
        // tick for unit-level coverage would require a heavy harness. The
        // structural correctness of the branchless predicate is what we
        // verify here; integration via fan_out is exercised by the existing
        // backtest replay tests once .B.1+.B.2+.B.3 land together.

        auto compute_stale_mask = [](uint8_t flags, uint64_t cached_publish_tick,
                                      uint64_t param_max_age_ticks,
                                      uint64_t tick_sequence) -> uint64_t {
            uint64_t stale_enabled  = (uint64_t)((flags & tt::GATE_FLAG_STALENESS_ENABLED) != 0);
            uint64_t has_stamp      = (uint64_t)(cached_publish_tick != 0);
            uint64_t tick_ge_stamp  = (uint64_t)(tick_sequence >= cached_publish_tick);
            uint64_t param_gap      = (tick_sequence - cached_publish_tick)
                                      & (uint64_t)(-(int64_t)tick_ge_stamp);
            uint64_t over_age       = (uint64_t)(param_gap > param_max_age_ticks);
            uint64_t stale          = stale_enabled & has_stamp & over_age;
            return (uint64_t)(-(int64_t)stale);
        };

        // === Test 1: gate disabled (flag=0) → mask always 0 ===
        check("v5.12.1.B.3: gate disabled → stale_mask = 0",
              compute_stale_mask(0, 100, 1000, 5000) == 0);

        // === Test 2: enabled + stamp=0 (warmup) → mask 0 ===
        check("v5.12.1.B.3: enabled + warmup stamp → stale_mask = 0",
              compute_stale_mask(tt::GATE_FLAG_STALENESS_ENABLED, 0, 1000, 5000) == 0);

        // === Test 3: enabled + gap < threshold → mask 0 ===
        check("v5.12.1.B.3: enabled + gap<threshold → stale_mask = 0",
              compute_stale_mask(tt::GATE_FLAG_STALENESS_ENABLED, 1000, 1000, 1500) == 0);

        // === Test 4: enabled + gap > threshold → mask = ALL_ONES ===
        check("v5.12.1.B.3: enabled + gap>threshold → stale_mask = ALL_ONES",
              compute_stale_mask(tt::GATE_FLAG_STALENESS_ENABLED, 1000, 1000, 5000) == ~(uint64_t)0);

        // === Test 5: counter-wrap defense (publish_tick > tick.sequence) ===
        check("v5.12.1.B.3: wrap defense → stale_mask = 0",
              compute_stale_mask(tt::GATE_FLAG_STALENESS_ENABLED, 1000, 1000, 500) == 0);

        // === Test 6: gap exactly at threshold (boundary) → not stale ===
        check("v5.12.1.B.3: gap == threshold → not stale (strict >)",
              compute_stale_mask(tt::GATE_FLAG_STALENESS_ENABLED, 1000, 1000, 2000) == 0);

        // === Test 7: gap = threshold + 1 → stale ===
        check("v5.12.1.B.3: gap == threshold+1 → stale",
              compute_stale_mask(tt::GATE_FLAG_STALENESS_ENABLED, 1000, 1000, 2001) == ~(uint64_t)0);

        // === Test 8: SHALT_PARAM_STALE registry sanity ===
        check("v5.12.1.B.3: SHALT_PARAM_STALE < NUM_SHALT_CODES",
              SHALT_PARAM_STALE < NUM_SHALT_CODES);
        check("v5.12.1.B.3: SHALT_SHORT_NAMES[SHALT_PARAM_STALE] == 'param-stale'",
              std::strcmp(SHALT_SHORT_NAMES[SHALT_PARAM_STALE], "param-stale") == 0);

        // === Test 9: cfg defaults ===
        ControllerConfig<64> cfg = ControllerConfig_Default<64>();
        check("v5.12.1.B.3: default cfg.param_staleness_gate_enabled == 0",
              cfg.param_staleness_gate_enabled == 0);
        check("v5.12.1.B.3: default cfg.param_max_age_ticks == 1000",
              cfg.param_max_age_ticks == 1000);

        // === Test 10: GATE_FLAG_STALENESS_ENABLED bit value ===
        check("v5.12.1.B.3: GATE_FLAG_STALENESS_ENABLED == 0x80",
              tt::GATE_FLAG_STALENESS_ENABLED == 0x80);
    }

    printf("\n--- v5.12.1.B.1: ParameterSlot publish_tick paired field ---\n");
    {
        // Phase B.1 of v5.12.1.B. Adds publish_ticks[2] parallel array
        // to ParameterSlot, plus optional publish_tick params on Write/Read.
        // Default 0 = legacy callers unchanged. Writer + reader pair the
        // tick value with the buffer atomically via the same seqlock.
        // The slow-path-write + hot-path-gate wiring lands in .B.2/.B.3.

        struct TestPayload {
            uint32_t value;
            uint32_t pad;
        };
        tt::ParameterSlot<TestPayload> slot;
        TestPayload init = {42, 0};
        tt::ParameterSlot_Init(&slot, init);

        // === Test 1: post-Init publish_ticks are 0 ===
        TestPayload out = {0, 0};
        uint64_t pt = 999;  // sentinel
        tt::ParameterSlot_Read(&slot, &out, &pt);
        check("v5.12.1.B.1: post-Init Read returns publish_tick = 0",
              pt == 0);
        check("v5.12.1.B.1: post-Init Read returns initial value",
              out.value == 42);

        // === Test 2: legacy Write (default publish_tick=0) preserves 0 ===
        TestPayload w1 = {100, 0};
        tt::ParameterSlot_Write(&slot, w1);  // no publish_tick → default 0
        tt::ParameterSlot_Read(&slot, &out, &pt);
        check("v5.12.1.B.1: legacy Write sets publish_tick = 0",
              pt == 0);
        check("v5.12.1.B.1: legacy Write payload round-trips",
              out.value == 100);

        // === Test 3: Write with explicit publish_tick round-trips ===
        TestPayload w2 = {200, 0};
        const uint64_t expected_tick = 0x1234567890ABCDEFULL;
        tt::ParameterSlot_Write(&slot, w2, expected_tick);
        tt::ParameterSlot_Read(&slot, &out, &pt);
        check("v5.12.1.B.1: Write with publish_tick round-trips tick",
              pt == expected_tick);
        check("v5.12.1.B.1: Write with publish_tick round-trips payload",
              out.value == 200);

        // === Test 4: legacy Read (no publish_tick out-param) still works ===
        TestPayload out2 = {0, 0};
        tt::ParameterSlot_Read(&slot, &out2);  // no out-param → ignored
        check("v5.12.1.B.1: legacy Read (no publish_tick) returns payload",
              out2.value == 200);

        // === Test 5: multiple writes — publish_tick paired with right buffer ===
        // Seqlock alternates buffers; verify publish_tick tracks index.
        for (uint64_t k = 1; k <= 8; ++k) {
            TestPayload p = {(uint32_t)(k * 1000), 0};
            tt::ParameterSlot_Write(&slot, p, k);
        }
        tt::ParameterSlot_Read(&slot, &out, &pt);
        check("v5.12.1.B.1: latest Write's publish_tick observed after burst",
              pt == 8);
        check("v5.12.1.B.1: latest Write's payload observed after burst",
              out.value == 8000);

        // === Test 6: sizeof(ParameterSlot) preserved at 64-byte stride ===
        // The struct gained 16 bytes (publish_ticks[2]); pad shrunk to absorb.
        // Total size MUST remain a multiple of 64 for cache-line isolation.
        check("v5.12.1.B.1: sizeof(ParameterSlot<TestPayload>) is multiple of 64",
              (sizeof(tt::ParameterSlot<TestPayload>) % 64) == 0);
    }

    printf("\n--- v5.12.1.A.3: recovery refusal + flatten_pending auto-clear ---\n");
    {
        // Phase A.3 of v5.12.1.A. CheckWsStaleness now sets
        // oms->recovery_until_us alongside flatten_pending. After the
        // window elapses, EventLoop_TryClearRecovery resets both atomics
        // so a future staleness event can re-fire.

        tt::OrderManagerState<64> oms;
        tt::ExchangeAdapter<64> empty_adapter{};
        tt::OrderManager_Init(&oms, empty_adapter, /*live=*/0,
                              FPN_FromDouble<64>(10000.0),
                              FPN_FromDouble<64>(0.001));
        tt::EventLoopState<64> state;
        tt::EventLoopState_Init(&state, &oms);
        ControllerConfig<64> cfg = ControllerConfig_Default<64>();
        cfg.ws_dead_time_flatten_enabled = 1;
        cfg.ws_dead_time_flatten_threshold_secs = 60;
        cfg.recovery_delay_secs = 30;

        // === Test 1: default cfg.recovery_delay_secs == 30 ===
        check("v5.12.1.A.3: default cfg.recovery_delay_secs == 30",
              ControllerConfig_Default<64>().recovery_delay_secs == 30);

        // === Test 2: post-Init recovery_until_us == 0 ===
        check("v5.12.1.A.3: oms.recovery_until_us defaults to 0",
              oms.recovery_until_us.load(std::memory_order_acquire) == 0);

        // === Test 3: CheckWsStaleness fire sets recovery_until_us ===
        {
            uint64_t last_us = 1000000000000ULL;
            uint64_t now_us  = last_us + 90ULL * 1000000ULL;  // 90s gap
            state.last_ws_tick_us.store(last_us, std::memory_order_release);
            oms.flatten_pending.store(0, std::memory_order_release);
            oms.recovery_until_us.store(0, std::memory_order_release);
            tt::EventLoop_CheckWsStaleness(&state, cfg, /*price*/100.0, now_us);
            uint64_t got = oms.recovery_until_us.load(std::memory_order_acquire);
            uint64_t want = now_us + 30ULL * 1000000ULL;
            check("v5.12.1.A.3: CheckWsStaleness fire sets recovery_until_us",
                  got == want);
        }

        // === Test 4: TryClearRecovery is no-op while inside window ===
        {
            uint64_t deadline = oms.recovery_until_us.load(std::memory_order_acquire);
            uint64_t now_us = deadline - 1000000ULL;  // 1s before deadline
            int cleared = tt::EventLoop_TryClearRecovery(&oms, now_us);
            check("v5.12.1.A.3: TryClearRecovery no-op inside recovery window",
                  cleared == 0);
            check("v5.12.1.A.3: recovery_until_us unchanged inside window",
                  oms.recovery_until_us.load(std::memory_order_acquire) == deadline);
            check("v5.12.1.A.3: flatten_pending stays 1 inside window",
                  oms.flatten_pending.load(std::memory_order_acquire) == 1);
        }

        // === Test 5: TryClearRecovery clears both atomics post-deadline ===
        {
            uint64_t deadline = oms.recovery_until_us.load(std::memory_order_acquire);
            uint64_t now_us = deadline + 1000000ULL;  // 1s after deadline
            int cleared = tt::EventLoop_TryClearRecovery(&oms, now_us);
            check("v5.12.1.A.3: TryClearRecovery returns 1 on first clear",
                  cleared == 1);
            check("v5.12.1.A.3: recovery_until_us == 0 after clear",
                  oms.recovery_until_us.load(std::memory_order_acquire) == 0);
            check("v5.12.1.A.3: flatten_pending == 0 after clear",
                  oms.flatten_pending.load(std::memory_order_acquire) == 0);
            // Second call → no-op (already cleared)
            int cleared2 = tt::EventLoop_TryClearRecovery(&oms, now_us);
            check("v5.12.1.A.3: TryClearRecovery returns 0 on second call",
                  cleared2 == 0);
        }

        // === Test 6: After clear, CheckWsStaleness can re-fire ===
        {
            uint64_t last_us = 2000000000000ULL;
            uint64_t now_us  = last_us + 90ULL * 1000000ULL;
            state.last_ws_tick_us.store(last_us, std::memory_order_release);
            // flatten_pending and recovery_until_us are 0 from Test 5
            tt::EventLoop_CheckWsStaleness(&state, cfg, 100.0, now_us);
            check("v5.12.1.A.3: re-fire after clear → flatten_pending=1",
                  oms.flatten_pending.load(std::memory_order_acquire) == 1);
            check("v5.12.1.A.3: re-fire after clear → recovery_until_us > 0",
                  oms.recovery_until_us.load(std::memory_order_acquire) > 0);
        }

        // === Test 7: SHALT_RECOVERY enum is registered + named ===
        check("v5.12.1.A.3: SHALT_RECOVERY < NUM_SHALT_CODES",
              SHALT_RECOVERY < NUM_SHALT_CODES);
        check("v5.12.1.A.3: SHALT_SHORT_NAMES[SHALT_RECOVERY] == 'recovery'",
              std::strcmp(SHALT_SHORT_NAMES[SHALT_RECOVERY], "recovery") == 0);

        tt::OrderManager_Shutdown(&oms);
    }

    printf("\n--- v5.12.1.A.2: WS-staleness gate + EventLoop_FlattenAll ---\n");
    {
        // Phase A.2 of v5.12.1.A. Adds EventLoop_FlattenAll +
        // EventLoop_CheckWsStaleness in ControllerEventLoop.hpp. Slow-path
        // CAS-coordinates so only one core fires the flatten when the
        // producer's last_ws_tick_us gap exceeds the threshold.
        //
        // Tests use synthetic now_us (caller-supplied) so the gate's math
        // is exercised deterministically without sleep/wallclock.

        tt::OrderManagerState<64> oms;
        tt::ExchangeAdapter<64> empty_adapter{};
        tt::OrderManager_Init(&oms, empty_adapter, /*live=*/0,
                              FPN_FromDouble<64>(10000.0),
                              FPN_FromDouble<64>(0.001));
        tt::EventLoopState<64> state;
        tt::EventLoopState_Init(&state, &oms);

        // Make a default config; verify our cfg fields parsed.
        ControllerConfig<64> cfg = ControllerConfig_Default<64>();
        check("v5.12.1.A.2: default cfg.ws_dead_time_flatten_enabled == 0",
              cfg.ws_dead_time_flatten_enabled == 0);
        check("v5.12.1.A.2: default cfg.ws_dead_time_flatten_threshold_secs == 60",
              cfg.ws_dead_time_flatten_threshold_secs == 60);

        // === Test 1: cfg flag=0 (default) → no flatten regardless of gap ===
        {
            state.last_ws_tick_us.store(1000ULL, std::memory_order_release);
            uint64_t huge_now_us = 1000000000000ULL;  // gap >> threshold
            int n = tt::EventLoop_CheckWsStaleness(&state, cfg, /*price*/100.0,
                                                    huge_now_us);
            check("v5.12.1.A.2: cfg flag=0 → CheckWsStaleness returns 0 "
                  "(no flatten path entered)", n == 0);
            check("v5.12.1.A.2: cfg flag=0 → flatten_pending stays 0",
                  oms.flatten_pending.load(std::memory_order_acquire) == 0);
        }

        // === Test 2: enabled + last==0 (warmup) → no flatten ===
        {
            cfg.ws_dead_time_flatten_enabled = 1;
            state.last_ws_tick_us.store(0ULL, std::memory_order_release);
            uint64_t huge_now_us = 1000000000000ULL;
            int n = tt::EventLoop_CheckWsStaleness(&state, cfg, 100.0, huge_now_us);
            check("v5.12.1.A.2: enabled + last==0 (warmup) → no flatten",
                  n == 0);
            check("v5.12.1.A.2: warmup → flatten_pending stays 0",
                  oms.flatten_pending.load(std::memory_order_acquire) == 0);
        }

        // === Test 3: enabled + gap < threshold → no flatten ===
        {
            uint64_t last_us  = 1000000000000ULL;             // some baseline
            uint64_t now_us   = last_us + 30ULL * 1000000ULL; // 30s gap
            state.last_ws_tick_us.store(last_us, std::memory_order_release);
            oms.flatten_pending.store(0, std::memory_order_release);
            int n = tt::EventLoop_CheckWsStaleness(&state, cfg, 100.0, now_us);
            check("v5.12.1.A.2: enabled + gap<threshold (30s vs 60s) → "
                  "no flatten",
                  n == 0);
            check("v5.12.1.A.2: gap<threshold → flatten_pending stays 0",
                  oms.flatten_pending.load(std::memory_order_acquire) == 0);
        }

        // === Test 4: enabled + gap > threshold + empty portfolio →
        //             CAS fires, but FlattenAll returns 0 (no positions) ===
        {
            uint64_t last_us  = 1000000000000ULL;
            uint64_t now_us   = last_us + 90ULL * 1000000ULL; // 90s gap
            state.last_ws_tick_us.store(last_us, std::memory_order_release);
            oms.flatten_pending.store(0, std::memory_order_release);
            // Portfolio is empty by default — bitmap=0 → FlattenAll
            // returns 0 but flatten_pending CAS still wins.
            int n = tt::EventLoop_CheckWsStaleness(&state, cfg, 100.0, now_us);
            check("v5.12.1.A.2: gap>threshold + empty portfolio → "
                  "FlattenAll returns 0 (no positions to close)", n == 0);
            check("v5.12.1.A.2: gap>threshold → flatten_pending=1 (CAS won)",
                  oms.flatten_pending.load(std::memory_order_acquire) == 1);
        }

        // === Test 5: second call after first fired → CAS loses, returns 0 ===
        {
            // flatten_pending is still 1 from Test 4. Caller should not
            // re-enter the flatten path.
            uint64_t last_us  = 1000000000000ULL;
            uint64_t now_us   = last_us + 90ULL * 1000000ULL;
            state.last_ws_tick_us.store(last_us, std::memory_order_release);
            int n = tt::EventLoop_CheckWsStaleness(&state, cfg, 100.0, now_us);
            check("v5.12.1.A.2: second call after fire → CAS lost, "
                  "no double-flatten",
                  n == 0);
            check("v5.12.1.A.2: flatten_pending stays 1 after duplicate call",
                  oms.flatten_pending.load(std::memory_order_acquire) == 1);
        }

        // === Test 6: FlattenAll on empty portfolio returns 0 ===
        {
            int n = tt::EventLoop_FlattenAll(&state, &oms, /*price*/100.0,
                                              /*reason*/9);
            check("v5.12.1.A.2: FlattenAll on empty bitmap returns 0",
                  n == 0);
        }

        // === Test 7: FlattenAll on portfolio with one open position ===
        {
            // Manually open a position in slot 0 to verify FlattenAll
            // pushes a market exit. With partial_exit_enabled=0 (default),
            // slot 0 == core 0.
            oms.flatten_pending.store(0, std::memory_order_release);
            oms.portfolio.active_bitmap = (uint16_t)0x0001;
            oms.portfolio.positions[0].quantity = FPN_FromDouble<64>(1.5);
            oms.portfolio.positions[0].entry_price = FPN_FromDouble<64>(50000.0);
            // Pre-condition: submit queue 0 should be empty (drainer
            // hasn't run). Capture head before; verify head increased.
            int submitted = tt::EventLoop_FlattenAll(&state, &oms, 50000.0,
                                                      /*reason*/2);
            check("v5.12.1.A.2: FlattenAll on 1-position portfolio "
                  "submits 1 exit",
                  submitted == 1);
            // Reset for cleanup
            oms.portfolio.active_bitmap = 0;
        }

        tt::OrderManager_Shutdown(&oms);
    }

    printf("\n--- v5.12.1.A.1: last_ws_tick_us field on EventLoopState ---\n");
    {
        // Phase A.1 of v5.12.1.A (Disconnect-flatten policy). Adds a
        // single global atomic on EventLoopState — wall-clock us of last
        // WS tick received. Producer (or backtest driver) is sole writer;
        // slow-path threads + GUI read with acquire ordering. Used by the
        // forthcoming staleness gate (sub-tag .A.2) to fire OMS_FlattenAll
        // when WS dropouts exceed cfg.ws_dead_time_flatten_threshold_secs.

        tt::OrderManagerState<64> oms;
        tt::ExchangeAdapter<64> empty_adapter{};
        tt::OrderManager_Init(&oms, empty_adapter, /*live=*/0,
                              FPN_FromDouble<64>(10000.0),
                              FPN_FromDouble<64>(0.001));
        tt::EventLoopState<64> state;
        tt::EventLoopState_Init(&state, &oms);

        // === Test 1: post-Init value is 0 (warmup sentinel) ===
        check("v5.12.1.A.1: last_ws_tick_us defaults to 0 post-Init",
              state.last_ws_tick_us.load(std::memory_order_acquire) == 0);

        // === Test 2: store + load round-trips ===
        const uint64_t synthetic_ts = 1778145938ULL;
        state.last_ws_tick_us.store(synthetic_ts, std::memory_order_release);
        check("v5.12.1.A.1: store + acquire-load returns the published value",
              state.last_ws_tick_us.load(std::memory_order_acquire) == synthetic_ts);

        // === Test 3: monotonic-on-store contract ===
        // Producer/backtest drivers publish strictly-increasing wall-clock
        // values. We verify successive stores update the read result; the
        // single-writer single-reader semantics make this trivial in a
        // unit test, but the field is sized + ordered for the multi-reader
        // case in production (slow-path + GUI both read concurrently).
        int monotonic_pass = 1;
        for (uint64_t k = 1; k <= 10; ++k) {
            uint64_t ts = synthetic_ts + k * 1000ULL;
            state.last_ws_tick_us.store(ts, std::memory_order_release);
            uint64_t got = state.last_ws_tick_us.load(std::memory_order_acquire);
            if (got != ts) { monotonic_pass = 0; break; }
        }
        check("v5.12.1.A.1: monotonic store/load on every step",
              monotonic_pass);

        tt::OrderManager_Shutdown(&oms);
    }

