    {
        // ML_Compute_RegimeTrendStrength — saturating clamp to [-1, 1].
        // x in range → identity; |x|>1 → ±1; null/missing → 0.
        RegimeSignals<64> sig;
        memset(&sig, 0, sizeof(sig));
        FeatureComputeCtx<64> ctx{};
        ctx.signals = &sig;

        // x = 0 → 0
        sig.short_slope = FPN_Zero<64>();
        check("v5.14.5.B: RegimeTrendStrength(x=0) = 0",
              FPN_IsZero(ML_Compute_RegimeTrendStrength(&ctx)));

        // x = 0.5 → 0.5 (in-range identity)
        sig.short_slope = FPN_FromDouble<64>(0.5);
        FPN<64> result = ML_Compute_RegimeTrendStrength(&ctx);
        check("v5.14.5.B: RegimeTrendStrength(x=0.5) ~= 0.5",
              std::abs(FPN_ToDouble(result) - 0.5) < 1e-6);

        // x = 5.0 → 1.0 (saturated upper)
        sig.short_slope = FPN_FromDouble<64>(5.0);
        result = ML_Compute_RegimeTrendStrength(&ctx);
        check("v5.14.5.B: RegimeTrendStrength(x=5) saturates to 1",
              std::abs(FPN_ToDouble(result) - 1.0) < 1e-6);

        // x = -5.0 → -1.0 (saturated lower)
        sig.short_slope = FPN_FromDouble<64>(-5.0);
        result = ML_Compute_RegimeTrendStrength(&ctx);
        check("v5.14.5.B: RegimeTrendStrength(x=-5) saturates to -1",
              std::abs(FPN_ToDouble(result) + 1.0) < 1e-6);

        // null ctx → 0 (defensive)
        check("v5.14.5.B: RegimeTrendStrength(null) = 0",
              FPN_IsZero(ML_Compute_RegimeTrendStrength<64>(nullptr)));
    }
    {
        // ML_Compute_RegimeVolZscore — (short_var - long_var) / sqrt(long_var).
        // Sign-carrying; long_var=0 → 0 (defensive).
        RegimeSignals<64> sig;
        memset(&sig, 0, sizeof(sig));
        FeatureComputeCtx<64> ctx{};
        ctx.signals = &sig;

        // long_var=0 → 0 (defensive: avoid div-by-zero)
        sig.short_variance = FPN_FromDouble<64>(1.0);
        sig.long_variance  = FPN_Zero<64>();
        check("v5.14.5.B: RegimeVolZscore(long_var=0) = 0",
              FPN_IsZero(ML_Compute_RegimeVolZscore(&ctx)));

        // short_var=long_var → 0 (no z-score)
        sig.short_variance = FPN_FromDouble<64>(4.0);
        sig.long_variance  = FPN_FromDouble<64>(4.0);
        FPN<64> result = ML_Compute_RegimeVolZscore(&ctx);
        check("v5.14.5.B: RegimeVolZscore(equal) ~= 0",
              std::abs(FPN_ToDouble(result)) < 1e-6);

        // short_var=8, long_var=4 → (8-4)/sqrt(4) = 4/2 = 2.0
        sig.short_variance = FPN_FromDouble<64>(8.0);
        sig.long_variance  = FPN_FromDouble<64>(4.0);
        result = ML_Compute_RegimeVolZscore(&ctx);
        check("v5.14.5.B: RegimeVolZscore(8, 4) ~= 2.0",
              std::abs(FPN_ToDouble(result) - 2.0) < 1e-3);

        // short_var=2, long_var=8 → (2-8)/sqrt(8) ~= -2.121
        sig.short_variance = FPN_FromDouble<64>(2.0);
        sig.long_variance  = FPN_FromDouble<64>(8.0);
        result = ML_Compute_RegimeVolZscore(&ctx);
        check("v5.14.5.B: RegimeVolZscore(2, 8) negative",
              FPN_ToDouble(result) < -1.5);

        // null ctx → 0 (defensive)
        check("v5.14.5.B: RegimeVolZscore(null) = 0",
              FPN_IsZero(ML_Compute_RegimeVolZscore<64>(nullptr)));
    }
    {
        // ML_Compute_RegimeClassOneHot — read ctx->current_regime as int.
        FeatureComputeCtx<64> ctx{};

        // Default 0 (REGIME_RANGING)
        ctx.current_regime = 0;
        check("v5.14.5.B: RegimeClassOneHot(0) = 0",
              FPN_IsZero(ML_Compute_RegimeClassOneHot(&ctx)));

        // current_regime=1 → 1
        ctx.current_regime = 1;
        FPN<64> result = ML_Compute_RegimeClassOneHot(&ctx);
        check("v5.14.5.B: RegimeClassOneHot(1) = 1",
              std::abs(FPN_ToDouble(result) - 1.0) < 1e-6);

        // current_regime=4 (max regime; depends on FOREACH_REGIME)
        ctx.current_regime = 4;
        result = ML_Compute_RegimeClassOneHot(&ctx);
        check("v5.14.5.B: RegimeClassOneHot(4) = 4",
              std::abs(FPN_ToDouble(result) - 4.0) < 1e-6);

        // null ctx → 0 (defensive)
        check("v5.14.5.B: RegimeClassOneHot(null) = 0",
              FPN_IsZero(ML_Compute_RegimeClassOneHot<64>(nullptr)));
    }
    {
        // Train-serve parity by construction — verify Features_PackAll
        // populates the 3 new features in the same buffer slots in
        // both LIVE and BACKTEST callers, given identical FeatureComputeCtx.
        // (Direct verification: same ctx → same buffer = parity by
        // construction, since both paths call Features_PackAll with the
        // same registry.)
        RegimeSignals<64> sig;
        memset(&sig, 0, sizeof(sig));
        sig.short_slope = FPN_FromDouble<64>(0.3);
        sig.short_variance = FPN_FromDouble<64>(2.0);
        sig.long_variance = FPN_FromDouble<64>(1.0);

        RollingStats<64> r = RollingStats_Init<64>();

        FeatureComputeCtx<64> ctx{};
        ctx.signals = &sig;
        ctx.short_rolling = &r;
        ctx.current_regime = 2;

        float buf[MODEL_MAX_FEATURES] = {0};
        int n = Features_PackAll(&ctx, buf);
        check("v5.14.5.B: Features_PackAll succeeds with regime fields",
              n >= 37);
        // Verify the 3 new features land in their registry positions.
        check("v5.14.5.B: regime_trend_strength populated correctly",
              std::abs(buf[FEATURE_REGIME_TREND_STRENGTH] - 0.3f) < 1e-3f);
        // (8 - 1) / sqrt(1) = 7 — wait, short_var=2, long_var=1 → (2-1)/sqrt(1) = 1
        check("v5.14.5.B: regime_vol_zscore populated correctly",
              std::abs(buf[FEATURE_REGIME_VOL_ZSCORE] - 1.0f) < 1e-3f);
        check("v5.14.5.B: regime_class_onehot populated from ctx",
              std::abs(buf[FEATURE_REGIME_CLASS_ONEHOT] - 2.0f) < 1e-3f);
    }

    // ----- v5.14.5.C: fractional differentiation features --------------------------------------------
    printf("\n--- v5.14.5.C: fractional differentiation features ---\n");
    {
        // Verify the 3 frac diff features are registered.
        check("v5.14.5.C: FEATURE_FRAC_DIFF_PRICE_D04 index assigned",
              FEATURE_FRAC_DIFF_PRICE_D04 >= 37);
        check("v5.14.5.C: FEATURE_FRAC_DIFF_PRICE_D05 index assigned",
              FEATURE_FRAC_DIFF_PRICE_D05 >= 37);
        check("v5.14.5.C: FEATURE_FRAC_DIFF_PRICE_D06 index assigned",
              FEATURE_FRAC_DIFF_PRICE_D06 >= 37);
        check("v5.14.5.C: NUM_REGISTERED_FEATURES bumped to >= 40",
              NUM_REGISTERED_FEATURES >= 40);
        check("v5.14.5.C: FEATURE_NAMES[FRAC_DIFF_PRICE_D04] correct",
              strcmp(FEATURE_NAMES[FEATURE_FRAC_DIFF_PRICE_D04],
                     "frac_diff_price_d04") == 0);
        check("v5.14.5.C: FEATURE_NAMES[FRAC_DIFF_PRICE_D05] correct",
              strcmp(FEATURE_NAMES[FEATURE_FRAC_DIFF_PRICE_D05],
                     "frac_diff_price_d05") == 0);
        check("v5.14.5.C: FEATURE_NAMES[FRAC_DIFF_PRICE_D06] correct",
              strcmp(FEATURE_NAMES[FEATURE_FRAC_DIFF_PRICE_D06],
                     "frac_diff_price_d06") == 0);
    }
    {
        // Coefficient table sanity — recurrence verification.
        // C(d, 0) = 1; C(d, 1) = d; C(d, 2) = d*(d-1)/2.
        check("v5.14.5.C: kFracDiff_d05_Coeffs[0] = 1.0",
              std::abs(kFracDiff_d05_Coeffs[0] - 1.0) < 1e-12);
        check("v5.14.5.C: kFracDiff_d05_Coeffs[1] = 0.5",
              std::abs(kFracDiff_d05_Coeffs[1] - 0.5) < 1e-12);
        // C(0.5, 2) = 0.5 * (-0.5) / 2 = -0.125
        check("v5.14.5.C: kFracDiff_d05_Coeffs[2] = -0.125",
              std::abs(kFracDiff_d05_Coeffs[2] - (-0.125)) < 1e-12);
        // C(0.4, 1) = 0.4
        check("v5.14.5.C: kFracDiff_d04_Coeffs[1] = 0.4",
              std::abs(kFracDiff_d04_Coeffs[1] - 0.4) < 1e-12);
        // C(0.6, 1) = 0.6
        check("v5.14.5.C: kFracDiff_d06_Coeffs[1] = 0.6",
              std::abs(kFracDiff_d06_Coeffs[1] - 0.6) < 1e-12);
        // Coefficients should decay toward 0 as k grows.
        check("v5.14.5.C: |C(d=0.5, k=49)| < 0.01 (decay sanity)",
              std::abs(kFracDiff_d05_Coeffs[49]) < 0.01);
    }
    {
        // Cold-start: count < K=50 → returns FPN_Zero.
        RollingStats<64> rs = RollingStats_Init<64>();
        FeatureComputeCtx<64> ctx{};
        ctx.short_rolling = &rs;
        check("v5.14.5.C: FracDiff_d04 cold-start returns 0",
              FPN_IsZero(ML_Compute_FracDiffPrice_d04(&ctx)));
        check("v5.14.5.C: FracDiff_d05 cold-start returns 0",
              FPN_IsZero(ML_Compute_FracDiffPrice_d05(&ctx)));
        check("v5.14.5.C: FracDiff_d06 cold-start returns 0",
              FPN_IsZero(ML_Compute_FracDiffPrice_d06(&ctx)));
        check("v5.14.5.C: null ctx returns 0",
              FPN_IsZero(ML_Compute_FracDiffPrice_d05<64>(nullptr)));
    }
    {
        // Steady-state: constant price input → frac diff converges to a
        // stable value (constant signal differentiated to its long-run
        // mean: x * sum(coeffs)). Sanity check finite + non-NaN.
        RollingStats<64> rs = RollingStats_Init<64>();
        // Push 60 ticks of constant price.
        for (int i = 0; i < 60; i++) {
            RollingStats_Push(&rs, FPN_FromDouble<64>(100.0),
                              FPN_FromDouble<64>(1.0), 0);
        }
        FeatureComputeCtx<64> ctx{};
        ctx.short_rolling = &rs;
        FPN<64> result = ML_Compute_FracDiffPrice_d05(&ctx);
        // Verify it computed something finite (not 0 since count >= 50).
        double r = FPN_ToDouble(result);
        check("v5.14.5.C: FracDiff_d05 on constant price computes finite",
              std::isfinite(r));
        // For constant input x=100, frac diff = 100 * Σ(-1)^k C(0.5,k).
        // Σ(-1)^k C(d,k) for k=0..∞ = (1-1)^d = 0 for d > 0. With K=50
        // truncation, residual ≈ |C(-0.5, 49)| ≈ 1/sqrt(π*49) ≈ 0.08 →
        // expected magnitude 100 * 0.08 ≈ 8.
        check("v5.14.5.C: FracDiff_d05 on constant price bounded (truncation residual)",
              std::abs(r) < 20.0);  // |residual| << input magnitude (100)
    }
    {
        // Trend: monotonic ramp price → frac diff captures fractional rate.
        // Push 60 ticks of linearly increasing price.
        RollingStats<64> rs = RollingStats_Init<64>();
        for (int i = 0; i < 60; i++) {
            RollingStats_Push(&rs, FPN_FromDouble<64>(100.0 + i * 0.5),
                              FPN_FromDouble<64>(1.0), 0);
        }
        FeatureComputeCtx<64> ctx{};
        ctx.short_rolling = &rs;
        FPN<64> r04 = ML_Compute_FracDiffPrice_d04(&ctx);
        FPN<64> r05 = ML_Compute_FracDiffPrice_d05(&ctx);
        FPN<64> r06 = ML_Compute_FracDiffPrice_d06(&ctx);
        check("v5.14.5.C: ramp → FracDiff_d04 finite",
              std::isfinite(FPN_ToDouble(r04)));
        check("v5.14.5.C: ramp → FracDiff_d05 finite",
              std::isfinite(FPN_ToDouble(r05)));
        check("v5.14.5.C: ramp → FracDiff_d06 finite",
              std::isfinite(FPN_ToDouble(r06)));
    }
    {
        // Replay determinism: same input → same output bytewise (FPN
        // arithmetic is deterministic; verifies no shared mutable state).
        RollingStats<64> rs1 = RollingStats_Init<64>();
        RollingStats<64> rs2 = RollingStats_Init<64>();
        for (int i = 0; i < 60; i++) {
            FPN<64> p = FPN_FromDouble<64>(100.0 + (i % 7) * 0.3);
            FPN<64> v = FPN_FromDouble<64>(1.0 + (i % 5) * 0.2);
            RollingStats_Push(&rs1, p, v, 0);
            RollingStats_Push(&rs2, p, v, 0);
        }
        FeatureComputeCtx<64> ctx1{};
        ctx1.short_rolling = &rs1;
        FeatureComputeCtx<64> ctx2{};
        ctx2.short_rolling = &rs2;
        FPN<64> r1 = ML_Compute_FracDiffPrice_d05(&ctx1);
        FPN<64> r2 = ML_Compute_FracDiffPrice_d05(&ctx2);
        // FPN<64> wraps a 4096-bit int internally — bytewise equality
        // is exact (no float rounding).
        check("v5.14.5.C: same input → bytewise identical FracDiff",
              memcmp(&r1, &r2, sizeof(r1)) == 0);
    }

    // ----- v5.14.4.B.2: Reconcile_AutoCancelStale (zombie cleanup; full AUTO_SYNC) ------------------
    printf("\n--- v5.14.4.B.2: AutoCancelStale helper ---\n");
    {
        // Test 1 — null orders → returns 0 (defensive)
        auto noop_cancel = [](const char*) -> int { return 1; };
        check("v5.14.4.B.2: AutoCancelStale null orders → 0",
              tt::Reconcile_AutoCancelStale(noop_cancel,
                  (tt::ReconcileOpenOrder*)nullptr, 5) == 0);
        tt::ReconcileOpenOrder dummy;
        check("v5.14.4.B.2: AutoCancelStale n_orders=0 → 0",
              tt::Reconcile_AutoCancelStale(noop_cancel, &dummy, 0) == 0);
    }
    {
        // Test 2 — All is_ours=0 (other-client orders) → none cancelled
        // (defensive: never touch non-engine orders even if list non-empty)
        tt::ReconcileOpenOrder orders[3];
        memset(orders, 0, sizeof(orders));
        orders[0].order_id = 100; orders[0].is_ours = 0;
        orders[1].order_id = 200; orders[1].is_ours = 0;
        orders[2].order_id = 300; orders[2].is_ours = 0;

        int call_count = 0;
        auto track_cancel = [&](const char*) -> int { call_count++; return 1; };

        int rc = tt::Reconcile_AutoCancelStale(track_cancel, orders, 3);
        check("v5.14.4.B.2: all is_ours=0 → 0 cancelled (defensive skip)",
              rc == 0);
        check("v5.14.4.B.2: cancel callable NEVER invoked when no is_ours orders",
              call_count == 0);
    }
    {
        // Test 3 — All is_ours=1 + cancel succeeds → all cancelled
        tt::ReconcileOpenOrder orders[3];
        memset(orders, 0, sizeof(orders));
        orders[0].order_id = 100; orders[0].is_ours = 1;
        orders[1].order_id = 200; orders[1].is_ours = 1;
        orders[2].order_id = 300; orders[2].is_ours = 1;

        std::vector<std::string> cancelled_ids;
        auto record_cancel = [&](const char* id) -> int {
            cancelled_ids.push_back(std::string(id));
            return 1;
        };

        int rc = tt::Reconcile_AutoCancelStale(record_cancel, orders, 3);
        check("v5.14.4.B.2: all is_ours=1 + success → 3 cancelled", rc == 3);
        check("v5.14.4.B.2: cancel callable invoked 3 times", cancelled_ids.size() == 3);
        check("v5.14.4.B.2: order_id correctly stringified (100)",
              cancelled_ids[0] == "100");
        check("v5.14.4.B.2: order_id correctly stringified (200)",
              cancelled_ids[1] == "200");
        check("v5.14.4.B.2: order_id correctly stringified (300)",
              cancelled_ids[2] == "300");
    }
    {
        // Test 4 — Mixed is_ours → only is_ours cancelled (defensive
        // selectivity preserved with mixed input)
        tt::ReconcileOpenOrder orders[5];
        memset(orders, 0, sizeof(orders));
        orders[0].order_id = 10; orders[0].is_ours = 1;
        orders[1].order_id = 20; orders[1].is_ours = 0;  // skip
        orders[2].order_id = 30; orders[2].is_ours = 1;
        orders[3].order_id = 40; orders[3].is_ours = 0;  // skip
        orders[4].order_id = 50; orders[4].is_ours = 1;

        std::vector<std::string> cancelled_ids;
        auto record_cancel = [&](const char* id) -> int {
            cancelled_ids.push_back(std::string(id));
            return 1;
        };

        int rc = tt::Reconcile_AutoCancelStale(record_cancel, orders, 5);
        check("v5.14.4.B.2: mixed is_ours → only 3 cancelled (10/30/50)", rc == 3);
        check("v5.14.4.B.2: skipped orders (20/40) NOT in cancel list",
              cancelled_ids.size() == 3 &&
              cancelled_ids[0] == "10" &&
              cancelled_ids[1] == "30" &&
              cancelled_ids[2] == "50");
    }
    {
        // Test 5 — Cancel partial fail → cancelled count reflects only success
        tt::ReconcileOpenOrder orders[4];
        memset(orders, 0, sizeof(orders));
        orders[0].order_id = 1; orders[0].is_ours = 1;
        orders[1].order_id = 2; orders[1].is_ours = 1;
        orders[2].order_id = 3; orders[2].is_ours = 1;
        orders[3].order_id = 4; orders[3].is_ours = 1;

        // Simulate fail on order_id 2 + 3 (e.g. "already cancelled" race)
        auto partial_fail_cancel = [](const char* id) -> int {
            if (strcmp(id, "2") == 0) return 0;  // fail
            if (strcmp(id, "3") == 0) return 0;  // fail
            return 1;
        };

        int rc = tt::Reconcile_AutoCancelStale(partial_fail_cancel, orders, 4);
        check("v5.14.4.B.2: 2/4 cancels fail → returns 2 (success count only)",
              rc == 2);
    }
    {
        // Test 6 — All cancels fail → returns 0 (no aborts; loop completes)
        tt::ReconcileOpenOrder orders[2];
        memset(orders, 0, sizeof(orders));
        orders[0].order_id = 1; orders[0].is_ours = 1;
        orders[1].order_id = 2; orders[1].is_ours = 1;

        int call_count = 0;
        auto always_fail = [&](const char*) -> int {
            call_count++;
            return 0;
        };

        int rc = tt::Reconcile_AutoCancelStale(always_fail, orders, 2);
        check("v5.14.4.B.2: all cancels fail → returns 0", rc == 0);
        check("v5.14.4.B.2: loop continues despite failures (best-effort) — 2 attempts",
              call_count == 2);
    }

    // ----- v5.14.4.B.1: Reconcile_ApplyMissedFills (replay-only AUTO_SYNC) --------------------------
    printf("\n--- v5.14.4.B.1: ApplyMissedFills helper ---\n");
    {
        // Test 1 — null/empty inputs → returns 0 (defensive)
        check("v5.14.4.B.1: ApplyMissedFills null oms → 0",
              tt::Reconcile_ApplyMissedFills<64>(nullptr, nullptr, 0) == 0);

        tt::OrderManagerState<64> oms;
        tt::EventLoopState<64> state;
        tt::EventLoopState_InitLegacy(&state, &oms,
            FPN_FromDouble<64>(10000.0), FPN_FromDouble<64>(0.001));
        check("v5.14.4.B.1: ApplyMissedFills null trades → 0",
              tt::Reconcile_ApplyMissedFills(&oms, (tt::ReconcileTrade*)nullptr, 5) == 0);
        check("v5.14.4.B.1: ApplyMissedFills n_trades=0 → 0",
              tt::Reconcile_ApplyMissedFills(&oms, (tt::ReconcileTrade*)nullptr, 0) == 0);
    }
    {
        // Test 2 — trade_id <= last_seen → skipped (idempotent re-run safety)
        tt::OrderManagerState<64> oms;
        tt::EventLoopState<64> state;
        tt::EventLoopState_InitLegacy(&state, &oms,
            FPN_FromDouble<64>(10000.0), FPN_FromDouble<64>(0.001));
        oms.last_seen_trade_id = 100;

        tt::ReconcileTrade trades[3];
        trades[0] = {.trade_id = 50,  .order_id = 1, .price = 50000.0, .qty = 0.001, .commission = 0, .time_ms = 0, .is_buyer = 1, .is_maker = 0};
        trades[1] = {.trade_id = 100, .order_id = 2, .price = 50000.0, .qty = 0.001, .commission = 0, .time_ms = 0, .is_buyer = 1, .is_maker = 0};
        trades[2] = {.trade_id = 99,  .order_id = 3, .price = 50000.0, .qty = 0.001, .commission = 0, .time_ms = 0, .is_buyer = 1, .is_maker = 0};

        int rc = tt::Reconcile_ApplyMissedFills(&oms, trades, 3);
        check("v5.14.4.B.1: trades all <= last_seen_trade_id → 0 replayed",
              rc == 0);
        check("v5.14.4.B.1: last_seen_trade_id unchanged (still 100)",
              oms.last_seen_trade_id == 100);
    }
    {
        // Test 3 — trade_id > last_seen → replayed; last_seen bumped to max
        tt::OrderManagerState<64> oms;
        tt::EventLoopState<64> state;
        tt::EventLoopState_InitLegacy(&state, &oms,
            FPN_FromDouble<64>(10000.0), FPN_FromDouble<64>(0.001));
        oms.last_seen_trade_id = 50;

        tt::ReconcileTrade trades[3];
        trades[0] = {.trade_id = 100, .order_id = 1, .price = 50000.0, .qty = 0.001, .commission = 0, .time_ms = 0, .is_buyer = 1, .is_maker = 0};
        trades[1] = {.trade_id = 200, .order_id = 2, .price = 50100.0, .qty = 0.001, .commission = 0, .time_ms = 0, .is_buyer = 1, .is_maker = 0};
        trades[2] = {.trade_id = 150, .order_id = 3, .price = 50050.0, .qty = 0.001, .commission = 0, .time_ms = 0, .is_buyer = 1, .is_maker = 0};

        int rc = tt::Reconcile_ApplyMissedFills(&oms, trades, 3);
        check("v5.14.4.B.1: trades all > last_seen → 3 replayed",
              rc == 3);
        check("v5.14.4.B.1: last_seen_trade_id bumped to max (200)",
              oms.last_seen_trade_id == 200);
    }
    {
        // Test 4 — mixed (some old, some new) → only new ones replayed
        tt::OrderManagerState<64> oms;
        tt::EventLoopState<64> state;
        tt::EventLoopState_InitLegacy(&state, &oms,
            FPN_FromDouble<64>(10000.0), FPN_FromDouble<64>(0.001));
        oms.last_seen_trade_id = 100;

        tt::ReconcileTrade trades[4];
        trades[0] = {.trade_id = 50,  .order_id = 1, .price = 50000.0, .qty = 0.001, .commission = 0, .time_ms = 0, .is_buyer = 1, .is_maker = 0};  // old
        trades[1] = {.trade_id = 150, .order_id = 2, .price = 50100.0, .qty = 0.001, .commission = 0, .time_ms = 0, .is_buyer = 1, .is_maker = 0};  // new
        trades[2] = {.trade_id = 100, .order_id = 3, .price = 50050.0, .qty = 0.001, .commission = 0, .time_ms = 0, .is_buyer = 1, .is_maker = 0};  // boundary (== last_seen → skipped)
        trades[3] = {.trade_id = 175, .order_id = 4, .price = 50075.0, .qty = 0.001, .commission = 0, .time_ms = 0, .is_buyer = 1, .is_maker = 0};  // new

        int rc = tt::Reconcile_ApplyMissedFills(&oms, trades, 4);
        check("v5.14.4.B.1: mixed old/new → 2 replayed (only > 100)",
              rc == 2);
        check("v5.14.4.B.1: last_seen_trade_id bumped to max new (175)",
              oms.last_seen_trade_id == 175);
    }
    {
        // Test 5 — idempotent re-run: replay then re-call → 0 the second time
        tt::OrderManagerState<64> oms;
        tt::EventLoopState<64> state;
        tt::EventLoopState_InitLegacy(&state, &oms,
            FPN_FromDouble<64>(10000.0), FPN_FromDouble<64>(0.001));

        tt::ReconcileTrade trades[2];
        trades[0] = {.trade_id = 100, .order_id = 1, .price = 50000.0, .qty = 0.001, .commission = 0, .time_ms = 0, .is_buyer = 1, .is_maker = 0};
        trades[1] = {.trade_id = 200, .order_id = 2, .price = 50100.0, .qty = 0.001, .commission = 0, .time_ms = 0, .is_buyer = 1, .is_maker = 0};

        int rc1 = tt::Reconcile_ApplyMissedFills(&oms, trades, 2);
        int rc2 = tt::Reconcile_ApplyMissedFills(&oms, trades, 2);
        check("v5.14.4.B.1: first call replays 2",  rc1 == 2);
        check("v5.14.4.B.1: re-run with same trades → 0 (idempotent)", rc2 == 0);
        check("v5.14.4.B.1: last_seen_trade_id stable across re-runs (200)",
              oms.last_seen_trade_id == 200);
    }

    // ----- v5.14.4.A: FOREACH_RECONCILE_MODE registry + cfg back-compat ------------------------------
    printf("\n--- v5.14.4.A: reconcile mode X-macro ---\n");
    {
        // Test 1 — Registry count static_assert (catches accidental shrinkage)
        static_assert(FOREACH_RECONCILE_MODE_COUNT >= 3,
            "v5.14.4.A: FOREACH_RECONCILE_MODE registry shrunk — was a mode removed?");
        check("v5.14.4.A: FOREACH_RECONCILE_MODE_COUNT >= 3 (STRICT/WARN/AUTO_SYNC)",
              FOREACH_RECONCILE_MODE_COUNT >= 3);
    }
    {
        // Test 2 — Enum values stable (operator cfgs may use numeric form)
        check("v5.14.4.A enum: RECONCILE_STRICT == 0", (int)tt::RECONCILE_STRICT == 0);
        check("v5.14.4.A enum: RECONCILE_WARN == 1", (int)tt::RECONCILE_WARN == 1);
        check("v5.14.4.A enum: RECONCILE_AUTO_SYNC == 2", (int)tt::RECONCILE_AUTO_SYNC == 2);
    }
    {
        // Test 3 — ToString round-trip
        check("v5.14.4.A: ToString(STRICT) == 'strict'",
              strcmp(tt::ReconcileMode_ToString(tt::RECONCILE_STRICT), "strict") == 0);
        check("v5.14.4.A: ToString(WARN) == 'warn'",
              strcmp(tt::ReconcileMode_ToString(tt::RECONCILE_WARN), "warn") == 0);
        check("v5.14.4.A: ToString(AUTO_SYNC) == 'auto_sync'",
              strcmp(tt::ReconcileMode_ToString(tt::RECONCILE_AUTO_SYNC), "auto_sync") == 0);
    }
    {
        // Test 4 — FromString round-trip
        tt::ReconcileMode mode;
        check("v5.14.4.A: FromString('strict') → STRICT",
              tt::ReconcileMode_FromString("strict", &mode) == 1 && mode == tt::RECONCILE_STRICT);
        check("v5.14.4.A: FromString('warn') → WARN",
              tt::ReconcileMode_FromString("warn", &mode) == 1 && mode == tt::RECONCILE_WARN);
        check("v5.14.4.A: FromString('auto_sync') → AUTO_SYNC",
              tt::ReconcileMode_FromString("auto_sync", &mode) == 1 && mode == tt::RECONCILE_AUTO_SYNC);
        check("v5.14.4.A: FromString('unknown') → 0 (no match)",
              tt::ReconcileMode_FromString("unknown", &mode) == 0);
    }
    {
        // Test 5 — Cfg defaults: reconcile_mode = WARN (matches legacy dry_run=1)
        ControllerConfig<64> cfg = ControllerConfig_Default<64>();
        check("v5.14.4.A cfg default: reconcile_mode = WARN (1)",
              cfg.reconcile_mode == 1);
        check("v5.14.4.A cfg default: reconcile_dry_run = 1 (legacy preserved)",
              cfg.reconcile_dry_run == 1);
    }
    {
        // Test 6 — Cfg parser back-compat: legacy reconcile_dry_run=0 → STRICT
        char tmp_cfg[] = "/tmp/v5_14_4_a_compat_XXXXXX";
        int fd = mkstemp(tmp_cfg);
        if (fd >= 0) {
            const char* contents = "reconcile_dry_run=0\n";
            write(fd, contents, strlen(contents));
            close(fd);
            ControllerConfig<64> cfg = ControllerConfig_Load<64>(tmp_cfg);
            check("v5.14.4.A back-compat: dry_run=0 → reconcile_mode = STRICT (0)",
                  cfg.reconcile_mode == 0);
            check("v5.14.4.A back-compat: dry_run=0 → reconcile_dry_run = 0 preserved",
                  cfg.reconcile_dry_run == 0);
            unlink(tmp_cfg);
        }
    }
    {
        // Test 7 — Cfg parser back-compat: legacy reconcile_dry_run=1 → WARN
        char tmp_cfg[] = "/tmp/v5_14_4_a_compat2_XXXXXX";
        int fd = mkstemp(tmp_cfg);
        if (fd >= 0) {
            const char* contents = "reconcile_dry_run=1\n";
            write(fd, contents, strlen(contents));
            close(fd);
            ControllerConfig<64> cfg = ControllerConfig_Load<64>(tmp_cfg);
            check("v5.14.4.A back-compat: dry_run=1 → reconcile_mode = WARN (1)",
                  cfg.reconcile_mode == 1);
            unlink(tmp_cfg);
        }
    }
    {
        // Test 8 — Cfg parser new field: reconcile_mode=auto_sync (string form)
        char tmp_cfg[] = "/tmp/v5_14_4_a_str_XXXXXX";
        int fd = mkstemp(tmp_cfg);
        if (fd >= 0) {
            const char* contents = "reconcile_mode=auto_sync\n";
            write(fd, contents, strlen(contents));
            close(fd);
            ControllerConfig<64> cfg = ControllerConfig_Load<64>(tmp_cfg);
            check("v5.14.4.A new field: reconcile_mode=auto_sync → 2",
                  cfg.reconcile_mode == 2);
            check("v5.14.4.A new field: dry_run mirrored (mode != STRICT → dry_run=1)",
                  cfg.reconcile_dry_run == 1);
            unlink(tmp_cfg);
        }
    }
    {
        // Test 9 — Cfg parser new field: reconcile_mode=2 (numeric form)
        char tmp_cfg[] = "/tmp/v5_14_4_a_num_XXXXXX";
        int fd = mkstemp(tmp_cfg);
        if (fd >= 0) {
            const char* contents = "reconcile_mode=2\n";
            write(fd, contents, strlen(contents));
            close(fd);
            ControllerConfig<64> cfg = ControllerConfig_Load<64>(tmp_cfg);
            check("v5.14.4.A new field: reconcile_mode=2 (numeric) → 2 (AUTO_SYNC)",
                  cfg.reconcile_mode == 2);
            unlink(tmp_cfg);
        }
    }

    // ----- v5.14.4.0: BinanceOrderAPI_CancelOrder + last_seen_trade_id ------------------------------
